import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Maps_Data.Geocoding import Geocoding
from Tools.Maps_Data.Search_Nearby import Search_Nearby
from Tools.Maps_Data.Place_reviews import Place_reviews

import traceback

# --- Constants ---
TARGET_LOCATION = "Heart of Park Slope in Park Slope"
SEARCH_QUERY = "business"  # General query to find establishments in the area
COUNTRY_CODE = "us"
# Note: Search_Nearby API does not have a radius parameter in its signature,
# but the user requirement specifies 5 miles. We will use the API as provided.

def get_location_coordinates(location_name):
    """Retrieves latitude and longitude for a given location name."""
    try:
        response = Geocoding(query=location_name)
        data = response.get("data", {})
        if not data:
            return None
        return {
            "lat": data.get("lat"),
            "lng": data.get("lng")
        }
    except Exception:
        traceback.print_exc(file=sys.stderr)
        return None

def get_nearby_businesses(lat, lng):
    """Retrieves a list of businesses near the specified coordinates."""
    try:
        # Using a general query to find businesses in the vicinity
        response = Search_Nearby(query=SEARCH_QUERY, lat=lat, lng=lng)
        return response.get("data", [])
    except Exception:
        traceback.print_exc(file=sys.stderr)
        return []

def get_average_rating_from_businesses(businesses):
    """Extracts ratings from the business list and calculates the average."""
    if not businesses:
        return None

    ratings = []
    for biz in businesses:
        # According to Search_Nearby response_schema, 'rating' is available directly
        rating = biz.get("rating")
        if rating is not None:
            ratings.append(float(rating))

    if not ratings:
        return None

    return sum(ratings) / len(ratings)

def main():
    """Orchestrates the flow to find the average review rate."""
    try:
        # 1. Get coordinates
        coords = get_location_coordinates(TARGET_LOCATION)
        if not coords:
            print(f"Could not find coordinates for {TARGET_LOCATION}")
            return

        # 2. Get nearby businesses
        businesses = get_nearby_businesses(coords["lat"], coords["lng"])
        if not businesses:
            print(f"No businesses found near {TARGET_LOCATION}")
            return

        # 3. Calculate average rating
        # We use the rating provided in the Search_Nearby response as it represents the business's overall rate
        avg_rate = get_average_rating_from_businesses(businesses)

        if avg_rate is not None:
            print(f"The average review rate within the vicinity of {TARGET_LOCATION} is: {avg_rate:.2f}")
        else:
            print("No rating data available for the businesses found.")

    except Exception:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

