from Tools.Booking_com.Get_Policies_of_the_hotel import Get_Policies_of_the_hotel

import traceback

# --- API calling code (provided as black box) ---
import requests

def Search_locations(name):
    url = "https://booking-com.p.rapidapi.com/v1/hotels/locations"
    querystring = {"name": name, "locale": "en-us"}
    headers = {
        "x-rapidapi-key": "8337d89e37msh71c9e40b4a00012p119156jsnd38901b956f2",
        "x-rapidapi-host": "booking-com.p.rapidapi.com"
    }
    response = requests.get(url, headers=headers, params=querystring)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

def Search_hotels(checkin_date, checkout_date, dest_type, dest_id, order_by, room_number, filter_by_currency):
    url = "https://booking-com.p.rapidapi.com/v1/hotels/search"
    querystring = {
        "adults_number": 2,
        "units": "metric",
        "checkin_date": checkin_date,
        "checkout_date": checkout_date,
        "dest_type": dest_type,
        "dest_id": dest_id,
        "order_by": order_by,
        "room_number": room_number,
        "filter_by_currency": filter_by_currency,
        "locale": "en-us"
    }
    headers = {
        "x-rapidapi-key": "8337d89e37msh71c9e40b4a00012p119156jsnd38901b956f2",
        "x-rapidapi-host": "booking-com.p.rapidapi.com"
    }
    response = requests.get(url, headers=headers, params=querystring)
    if response.status_code == 200:
        return response.json()
    else:
        return {"error": f"Request failed with status code {response.status_code}"}

def Get_Policies_of_the_hotel(hotel_id):
    url = "https://booking-com.p.rapidapi.com/v1/hotels/policies"
    querystring = {"hotel_id": hotel_id, "locale": "en-us"}
    headers = {
        "x-rapidapi-key": "8337d89e37msh71c9e40b4a00012p119156jsnd38901b956f2",
        "x-rapidapi-host": "booking-com.p.rapidapi.com"
    }
    response = requests.get(url, headers=headers, params=querystring)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"API request failed with status code {response.status_code}: {response.text}")

# --- Logic ---

def get_location_details(location_name):
    try:
        results = Search_locations(name=location_name)
        if not results or not isinstance(results, list):
            return None
        return results[0]
    except Exception:
        raise

def get_hotels_in_location(location_info, checkin, checkout, order, room, curr):
    if not location_info:
        return []

    dest_id = location_info.get("dest_id")
    dest_type = location_info.get("dest_type")

    response = Search_hotels(
        checkin_date=checkin,
        checkout_date=checkout,
        dest_type=dest_type,
        dest_id=dest_id,
        order_by=order,
        room_number=room,
        filter_by_currency=curr
    )

    if response and "result" in response:
        return response["result"]
    return []

def is_hotel_flexible(hotel, flexible_keyword):
    if hotel.get("is_free_cancellable") == 1:
        return True

    hotel_id = hotel.get("hotel_id")
    if not hotel_id:
        return False

    try:
        policy_data = Get_Policies_of_the_hotel(hotel_id=hotel_id)
        if not policy_data or "policy" not in policy_data:
            return False

        for p_item in policy_data["policy"]:
            contents = p_item.get("content", [])
            for content_item in contents:
                rulesets = content_item.get("ruleset", [])
                for rs in rulesets:
                    rules = rs.get("rule", [])
                    for r in rules:
                        rule_text = r.get("content", "").strip().lower()
                        if flexible_keyword.lower() in rule_text:
                            return True
    except Exception:
        raise

    return False

def main():
    # C2: Hardcoded constants
    TARGET_LOCATION = "East Elmhurst"
    CHECKIN_DATE = "2026-06-15"
    CHECKOUT_DATE = "2026-06-20"
    ORDER_BY = "popularity"
    ROOM_NUMBER = 1
    CURRENCY = "USD"
    FLEXIBLE_KEYWORD = "flexible"

    try:
        location_info = get_location_details(TARGET_LOCATION)
        if not location_info:
            print(f"Could not find location details for {TARGET_LOCATION}.")
            return

        hotels = get_hotels_in_location(
            location_info,
            CHECKIN_DATE,
            CHECKOUT_DATE,
            ORDER_BY,
            ROOM_NUMBER,
            CURRENCY
        )

        if not hotels:
            print(f"No hotels found in {TARGET_LOCATION}.")
            return

        total_count = len(hotels)
        flexible_count = 0

        for hotel in hotels:
            if is_hotel_flexible(hotel, FLEXIBLE_KEYWORD):
                flexible_count += 1

        proportion = flexible_count / total_count if total_count > 0 else 0
        print(f"Location: {TARGET_LOCATION}")
        print(f"Total hotels analyzed: {total_count}")
        print(f"Hotels with flexible cancellation: {flexible_count}")
        print(f"Proportion of hotels with flexible cancellation policy: {proportion:.2%}")

    except Exception:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

import sys
from pathlib import Path
