from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Hotel_data import Get_Hotel_data

import requests
import traceback
from datetime import datetime, date
import os

# ========================
# Module‑level constants (Rule 13)
# ========================
LOCATION_NAME = "NoHo"
CHECKIN_DATE = "2026-12-15"
CHECKOUT_DATE = "2026-12-20"
ORDER_BY = "price"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"

# ========================
# API functions (already implemented, directly callable)
# ========================

def Search_locations(name):
    url = "https://booking-com.p.rapidapi.com/v1/hotels/locations"
    querystring = {"name": name, "locale": "en-us"}
    rapid_api_key = os.getenv('RAPID_API_KEY')
    headers = {
        "x-rapidapi-key": rapid_api_key,
        "x-rapidapi-host": "booking-com.p.rapidapi.com"
    }
    response = requests.get(url, headers=headers, params=querystring)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"API request failed with status code {response.status_code}: {response.text}")


def Search_hotels(checkin_date, checkout_date, dest_type, dest_id, order_by, room_number, filter_by_currency):
    url = "https://booking-com.p.rapidapi.com/v1/hotels/search"
    querystring = {
        "adults_number": 2,
        "units": "metric",
        "checkin_date": checkin_date,
        "checkout_date": checkout_date,
        "dest_type": dest_type,
        "dest_id": dest_id,
        "order_by": order_by,
        "room_number": room_number,
        "filter_by_currency": filter_by_currency,
        "locale": "en-us"
    }
    rapid_api_key = os.getenv('RAPID_API_KEY')
    headers = {
        "x-rapidapi-key": rapid_api_key,
        "x-rapidapi-host": "booking-com.p.rapidapi.com"
    }
    response = requests.get(url, headers=headers, params=querystring)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"API request failed with status code {response.status_code}: {response.text}")


def Get_Hotel_data(hotel_id):
    url = "https://booking-com.p.rapidapi.com/v1/hotels/data"
    querystring = {"hotel_id": hotel_id, "locale": "en-us"}
    rapid_api_key = os.getenv('RAPID_API_KEY')
    headers = {
        "x-rapidapi-key": rapid_api_key,
        "x-rapidapi-host": "booking-com.p.rapidapi.com"
    }
    response = requests.get(url, headers=headers, params=querystring)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"API request failed with status code {response.status_code}: {response.text}")


# ========================
# Helper functions
# ========================

def search_destination(query):
    results = Search_locations(query)
    if not results:
        raise ValueError(f"No locations found for query '{query}'")
    for loc in results:
        name = loc.get("name", "")
        if query.lower() in name.lower().replace("®", "").replace("™", "").replace("©", ""):
            return {
                "dest_id": loc["dest_id"],
                "dest_type": loc["dest_type"]
            }
    first = results[0]
    return {
        "dest_id": first["dest_id"],
        "dest_type": first["dest_type"]
    }


def search_hotels(dest_id, dest_type):
    resp = Search_hotels(
        checkin_date=CHECKIN_DATE,
        checkout_date=CHECKOUT_DATE,
        dest_type=dest_type,
        dest_id=dest_id,
        order_by=ORDER_BY,
        room_number=ROOM_NUMBER,
        filter_by_currency=FILTER_BY_CURRENCY
    )
    if "error" in resp:
        raise RuntimeError(f"Hotel search failed: {resp['error']}")
    return resp.get("result", [])


def find_lowest_price_hotel(hotels_list):
    if not hotels_list:
        raise ValueError("No hotels found for the given destination")
    best = min(hotels_list, key=lambda h: h.get("min_total_price", float('inf')))
    return best


def get_hotel_details(hotel_id):
    return Get_Hotel_data(hotel_id)


def format_recommendation(hotel, details):
    name = hotel.get("hotel_name", "Unknown")
    price = hotel.get("min_total_price", "N/A")
    currency = hotel.get("currency_code", FILTER_BY_CURRENCY)
    return (
        f"Recommended: {name}\n"
        f"Total price (including taxes/fees): {price} {currency}\n"
        f"Check‑in: {CHECKIN_DATE}  Check‑out: {CHECKOUT_DATE}\n"
        f"Room: 1 room for 2 adults"
    )


# ========================
# Main orchestrator
# ========================
def main():
    dest = search_destination(LOCATION_NAME)
    dest_id = dest["dest_id"]
    dest_type = dest["dest_type"]
    print(f"Destination found: {LOCATION_NAME} (id={dest_id}, type={dest_type})")

    hotels = search_hotels(dest_id, dest_type)
    print(f"Found {len(hotels)} hotels")

    cheapest = find_lowest_price_hotel(hotels)
    print(f"Cheapest hotel in list: {cheapest.get('hotel_name')} (price={cheapest.get('min_total_price')})")

    hotel_id = cheapest.get("hotel_id")
    if not hotel_id:
        raise ValueError("Hotel result missing 'hotel_id'")
    details = get_hotel_details(hotel_id)

    message = format_recommendation(cheapest, details)
    print("\n" + "=" * 50)
    print(message)


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

