from Tools.Forward_and_Reverse_Geocoding.GeocodingSearch import GeocodingSearch
from Tools.Local_Business_Data.Search_Nearby import Search_Nearby
from Tools.Local_Business_Data.Search_Nearby import Search_Nearby

import traceback

QUERY_ROLLER_CITY = "Roller City"
QUERY_HIMALAYAN_BUSINESSES = "Himalayan/Nepalese"

def geocode_roller_city():
    response = GeocodingSearch(q=QUERY_ROLLER_CITY)
    if response:
        return response[0]['lat'], response[0]['lon']
    else:
        raise Exception("Failed to geocode Roller City")

def search_nearby_himalayan_businesses(lat, lng):
    response = Search_Nearby(query=QUERY_HIMALAYAN_BUSINESSES, lat=lat, lng=lng)
    if response and 'data' in response:
        return response['data']
    else:
        raise Exception("Failed to search nearby Himalayan/Nepalese businesses")

def determine_nearest_business(businesses, lat, lng):
    nearest_business = None
    min_distance = float('inf')
    for business in businesses:
        business_lat = business['latitude']
        business_lng = business['longitude']
        distance = ((float(business_lat) - float(lat)) ** 2 + (float(business_lng) - float(lng)) ** 2) ** 0.5
        if distance < min_distance:
            min_distance = distance
            nearest_business = business
    return nearest_business

def main():
    try:
        roller_city_lat, roller_city_lng = geocode_roller_city()
        nearby_businesses = search_nearby_himalayan_businesses(roller_city_lat, roller_city_lng)
        nearest_business = determine_nearest_business(nearby_businesses, roller_city_lat, roller_city_lng)
        print(nearest_business['name'])
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

import sys
