from Tools.Forward_and_Reverse_Geocoding.ForwardGeocoding import ForwardGeocoding
from Tools.Local_Business_Data.Search_Nearby import Search_Nearby
from Tools.Local_Business_Data.Business_Details import Business_Details
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

ADDRESS = "2428 Nolensville Rd"
QUERY = "Rock Climbing"
REGION = "us"

def geocode_address(address):
    street, city, state, postalcode, country = address, "", "", "", "USA"
    response = ForwardGeocoding("json", street, city, state, postalcode, country, "1", "en", "0", "1", "0", "0", "0", "0", "0", "0.0")
    if response:
        lat = response[0].get('lat')
        lon = response[0].get('lon')
        return lat, lon
    return None, None

def search_nearby_businesses(lat, lng):
    response = Search_Nearby(QUERY, float(lat), float(lng))
    if response.get('status') == 'OK' and response.get('data'):
        business_ids = [business.get('business_id') for business in response['data']]
        return business_ids
    return []

def get_business_details(business_ids):
    top_business = None
    top_rating = 0
    for business_id in business_ids:
        response = Business_Details(business_id, REGION)
        if response.get('status') == 'OK' and response.get('data'):
            business = response['data'][0]
            rating = business.get('rating', 0)
            if rating > top_rating:
                top_rating = rating
                top_business = business
    return top_business

def main():
    try:
        lat, lon = geocode_address(ADDRESS)
        if lat and lon:
            business_ids = search_nearby_businesses(lat, lon)
            top_business = get_business_details(business_ids)
            if top_business:
                print(f"Recommended Rock Climbing business: {top_business.get('name')} with rating {top_business.get('rating')}")
            else:
                print("No Rock Climbing businesses found nearby.")
        else:
            print("Failed to geocode address.")
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

