from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

# Constants
QUERY = "businesses"
REGION = "us"
ZOOM = 13
COUNTRY_NAME = "United States"
STATE_NAME = "Missouri"
CITY_NAME = "Maryland Heights"

def get_country_code():
    # Assuming there's an API call to get all countries and their ISO codes
    # For simplicity, we'll directly return the country code for "United States"
    # In a real scenario, you would call the API and parse the response
    return "US"

def get_state_code(country_code):
    # Assuming there's an API call to get states by country code
    # For simplicity, we'll directly return the state code for "Missouri"
    # In a real scenario, you would call the API and parse the response
    states_response = {
        "data": [
            {"state_code": "MO", "name": "Missouri"}
        ]
    }
    for state in states_response["data"]:
        if state["name"] == STATE_NAME:
            return state["state_code"]
    return None

def get_city_coordinates(country_code, state_code):
    # Assuming there's an API call to get cities by country code and state code
    # For simplicity, we'll directly return the coordinates for "Maryland Heights"
    # In a real scenario, you would call the API and parse the response
    cities_response = {
        "data": [
            {"name": "Maryland Heights", "latitude": 38.7133, "longitude": -90.4298}
        ]
    }
    for city in cities_response["data"]:
        if city["name"] == CITY_NAME:
            return city["latitude"], city["longitude"]
    return None, None

def search_businesses_in_area(lat, lng):
    response = Search_In_Area(QUERY, lat, lng, ZOOM)
    business_ids = [business["business_id"] for business in response["data"]]
    return business_ids

def retrieve_business_details(business_ids):
    business_statuses = []
    for business_id in business_ids:
        response = Business_Details(business_id, REGION)
        if response["data"]:
            business_status = response["data"][0].get("opening_status")
            business_statuses.append(business_status)
    return business_statuses

def count_not_open_businesses(business_statuses):
    count = 0
    for status in business_statuses:
        if status and ("closed" in status.lower() or "not open" in status.lower()):
            count += 1
    return count

def main():
    try:
        country_code = get_country_code()
        state_code = get_state_code(country_code)
        lat, lng = get_city_coordinates(country_code, state_code)
        business_ids = search_businesses_in_area(lat, lng)
        business_statuses = retrieve_business_details(business_ids)
        count = count_not_open_businesses(business_statuses)
        print(f"Number of businesses not open currently in {CITY_NAME}: {count}")
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

import sys
from pathlib import Path
