    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details
from Tools.Local_Business_Data.Business_Reviews import Business_Reviews
from Tools.Local_Business_Data.Business_Reviews import Business_Reviews

import traceback

QUERY = "Arts & Entertainment in Florissant"
REGION = "us"
BUSINESS_TYPE = "Arts & Entertainment"

def search_arts_entertainment_businesses():
    response = Search(QUERY)
    business_ids = [item['business_id'] for item in response['data']]
    return business_ids

def retrieve_business_details(business_ids):
    business_details = []
    for business_id in business_ids:
        response = Business_Details(business_id, REGION)
        business_details.extend(response['data'])
    return business_details

def extract_star_ratings(business_details):
    star_ratings = []
    for business_detail in business_details:
        if 'rating' in business_detail and business_detail['rating'] is not None:
            star_ratings.append(business_detail['rating'])
        else:
            response = Business_Reviews(business_detail['business_id'])
            ratings = [item['rating'] for item in response['data']]
            if ratings:
                star_ratings.append(sum(ratings) / len(ratings))
    return star_ratings

def calculate_average_star_rating(star_ratings):
    if not star_ratings:
        return 0
    return sum(star_ratings) / len(star_ratings)

def main():
    try:
        business_ids = search_arts_entertainment_businesses()
        business_details = retrieve_business_details(business_ids)
        star_ratings = extract_star_ratings(business_details)
        average_star_rating = calculate_average_star_rating(star_ratings)
        print(f"The average star rating of {BUSINESS_TYPE} businesses in Florissant is: {average_star_rating:.2f}")
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

