REGION = "us"

def search_pet_groomers_in_hermitage():
    response = Search_In_Area(QUERY, LATITUDE, LONGITUDE, ZOOM)
    business_ids = [business["business_id"] for business in response["data"]]
    return business_ids

def get_business_details(business_ids):
    star_ratings = []
    for business_id in business_ids:
        response = Business_Details(business_id, REGION)
        if response["data"]:
            star_ratings.append(response["data"][0].get("rating"))
    return star_ratings

def calculate_average_star_rating(star_ratings):
    valid_ratings = [rating for rating in star_ratings if rating is not None]
    if valid_ratings:
        return sum(valid_ratings) / len(valid_ratings)
    else:
        return None

def main():
    try:
        business_ids = search_pet_groomers_in_hermitage()
        star_ratings = get_business_details(business_ids)
        average_rating = calculate_average_star_rating(star_ratings)
        if average_rating is not None:
            print(f"The average star rating of Pet Groomers businesses in Hermitage is {average_rating:.2f}")
        else:
            print("No valid star ratings found for Pet Groomers businesses in Hermitage")
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

