# Constants
ADDRESS = "Spring House, PA"
QUERY = "business"
REGION = "us"

def geocode_spring_house():
    response = ForwardGeocoding(
        format="json",
        street="",
        city="Spring House",
        state="PA",
        postalcode="",
        country="USA",
        addressdetails="1",
        accept_language="en",
        namedetails="0",
        limit="1",
        bounded="",
        polygon_text="0",
        polygon_kml="0",
        polygon_svg="0",
        polygon_geojson="0",
        polygon_threshold="0.0"
    )
    if response:
        return response[0].get("lat"), response[0].get("lon")
    else:
        raise Exception("Geocoding failed")

def search_nearby_businesses(lat, lng):
    response = Search_Nearby(query=QUERY, lat=lat, lng=lng)
    if response.get("status") == "OK" and response.get("data"):
        return response.get("data")
    else:
        raise Exception("Search nearby businesses failed")

def extract_postal_codes(businesses):
    postal_codes = []
    for business in businesses:
        business_id = business.get("business_id")
        if business_id:
            details = Business_Details(business_id=business_id, region=REGION)
            if details.get("data"):
                postal_code = details.get("data")[0].get("zipcode")
                if postal_code:
                    postal_codes.append(postal_code)
    return postal_codes

def count_businesses_by_postal_code(postal_codes):
    counts = {}
    for code in postal_codes:
        counts[code] = counts.get(code, 0) + 1
    return counts

def identify_most_common_postal_code(counts):
    if counts:
        return max(counts, key=counts.get)
    else:
        raise Exception("No postal codes found")

def main():
    try:
        lat, lng = geocode_spring_house()
        nearby_businesses = search_nearby_businesses(lat, lng)
        postal_codes = extract_postal_codes(nearby_businesses)
        postal_code_counts = count_businesses_by_postal_code(postal_codes)
        most_common_postal_code = identify_most_common_postal_code(postal_code_counts)
        print(most_common_postal_code)
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Forward_and_Reverse_Geocoding.ForwardGeocoding import ForwardGeocoding
from Tools.Local_Business_Data.Search_In_Area import Search_In_Area
from Tools.Local_Business_Data.Business_Details import Business_Details
from Tools.Local_Business_Data.Business_Details import Business_Details
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

CITY = "Brentwood"
STATE = "MO"
COUNTRY = "US"
QUERY = "business"
ZOOM = 13
REGION = "us"

def get_coordinates_of_brentwood():
    response = ForwardGeocoding(
        format="json",
        street="",
        city=CITY,
        state=STATE,
        postalcode="",
        country=COUNTRY,
        addressdetails="1",
        accept_language="en",
        namedetails="0",
        limit=1,
        bounded="0",
        polygon_text="0",
        polygon_kml="0",
        polygon_svg="0",
        polygon_geojson="0",
        polygon_threshold="0.0"
    )
    if response:
        lat = response[0].get('lat')
        lon = response[0].get('lon')
        return lat, lon
    return None, None

def search_businesses_in_area(lat, lng):
    response = Search_In_Area(query=QUERY, lat=lat, lng=lng, zoom=ZOOM)
    if response and response.get('status') == 'OK':
        return response.get('data', [])
    return []

def extract_and_count_postal_codes(businesses):
    postal_code_counts = {}
    for business in businesses:
        business_id = business.get('business_id')
        if business_id:
            business_details = Business_Details(business_id=business_id, region=REGION)
            if business_details and business_details.get('data'):
                zipcode = business_details['data'][0].get('zipcode')
                if zipcode:
                    postal_code_counts[zipcode] = postal_code_counts.get(zipcode, 0) + 1
    return postal_code_counts

def identify_most_common_postal_code(postal_code_counts):
    if postal_code_counts:
        return max(postal_code_counts, key=postal_code_counts.get)
    return None

def main():
    try:
        lat, lng = get_coordinates_of_brentwood()
        if lat and lng:
            businesses = search_businesses_in_area(lat, lng)
            postal_code_counts = extract_and_count_postal_codes(businesses)
            most_common_postal_code = identify_most_common_postal_code(postal_code_counts)
            if most_common_postal_code:
                print(f"The postal code region with the most businesses in {CITY}, {STATE} is: {most_common_postal_code}")
            else:
                print(f"No businesses found in {CITY}, {STATE}.")
        else:
            print(f"Failed to get coordinates for {CITY}, {STATE}.")
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()
